(function(){
var M = {"W":2561,"H":1463,"HEADER_H":34,"ROW_H":19,"nodes":[{"id":"USERS","cluster":"identity","x":70,"y":212,"w":210,"h":156,"fullH":156,"n":6},{"id":"CLIENTS","cluster":"identity","x":70,"y":398,"w":210,"h":175,"fullH":175,"n":7},{"id":"ROLES","cluster":"identity","x":70,"y":603,"w":210,"h":99,"fullH":99,"n":3},{"id":"PERMISSIONS","cluster":"identity","x":70,"y":732,"w":210,"h":99,"fullH":99,"n":3},{"id":"MODEL_HAS_ROLES","cluster":"identity","x":70,"y":861,"w":210,"h":99,"fullH":99,"n":3},{"id":"MODEL_HAS_PERMISSIONS","cluster":"identity","x":70,"y":990,"w":251,"h":99,"fullH":99,"n":3},{"id":"ROLE_HAS_PERMISSIONS","cluster":"identity","x":70,"y":1119,"w":242,"h":80,"fullH":80,"n":2},{"id":"PERSONAL_ACCESS_TOKENS","cluster":"identity","x":70,"y":1229,"w":260,"h":118,"fullH":118,"n":4},{"id":"NOTIFICATIONS","cluster":"identity","x":376,"y":212,"w":210,"h":137,"fullH":137,"n":5},{"id":"ACTIVITY_LOGS","cluster":"identity","x":376,"y":379,"w":210,"h":175,"fullH":175,"n":7},{"id":"PASSWORD_RESET_TOKENS","cluster":"identity","x":376,"y":584,"w":251,"h":80,"fullH":80,"n":2},{"id":"CLIENT_PASSWORD_RESET_TOKENS","cluster":"identity","x":376,"y":694,"w":315,"h":80,"fullH":80,"n":2},{"id":"COMPANIES","cluster":"org","x":811,"y":212,"w":210,"h":137,"fullH":137,"n":5},{"id":"DEPARTMENTS","cluster":"org","x":811,"y":379,"w":210,"h":137,"fullH":137,"n":5},{"id":"DESIGNATIONS","cluster":"org","x":811,"y":546,"w":210,"h":99,"fullH":99,"n":3},{"id":"EMPLOYEES","cluster":"org","x":811,"y":675,"w":210,"h":213,"fullH":213,"n":9},{"id":"TEAMS","cluster":"org","x":811,"y":918,"w":210,"h":156,"fullH":156,"n":6},{"id":"TEAM_MEMBERS","cluster":"org","x":811,"y":1104,"w":210,"h":118,"fullH":118,"n":4},{"id":"PROJECTS","cluster":"projects","x":1141,"y":212,"w":248,"h":403,"fullH":403,"n":19},{"id":"PROJECT_MILESTONES","cluster":"projects","x":1141,"y":645,"w":223,"h":213,"fullH":213,"n":9},{"id":"SALES_REPORTS","cluster":"projects","x":1141,"y":888,"w":210,"h":194,"fullH":194,"n":8},{"id":"PROJECT_SALES","cluster":"projects","x":1141,"y":1112,"w":248,"h":213,"fullH":213,"n":9},{"id":"PROJECT_ASSIGNMENTS","cluster":"projects","x":1435,"y":212,"w":232,"h":194,"fullH":194,"n":8},{"id":"PROJECT_NOTES","cluster":"projects","x":1435,"y":436,"w":210,"h":137,"fullH":137,"n":5},{"id":"CALL_CENTER_AGENTS","cluster":"callcenter","x":1787,"y":212,"w":223,"h":118,"fullH":118,"n":4},{"id":"CALL_CENTER_PICKS","cluster":"callcenter","x":1787,"y":360,"w":214,"h":289,"fullH":289,"n":13},{"id":"CALL_CENTER_ACTIVITIES","cluster":"callcenter","x":1787,"y":679,"w":260,"h":213,"fullH":213,"n":9},{"id":"LLB Logo_ORDERS","cluster":"LLB Logo","x":2167,"y":212,"w":210,"h":270,"fullH":270,"n":12},{"id":"LLB Logo_ORDER_ITEMS","cluster":"LLB Logo","x":2167,"y":512,"w":210,"h":175,"fullH":175,"n":7},{"id":"LLB Logo_ORDER_SHIPPING_ADDRESSES","cluster":"LLB Logo","x":2167,"y":717,"w":278,"h":137,"fullH":137,"n":5},{"id":"LLB Logo_ORDER_LOGS","cluster":"LLB Logo","x":2167,"y":884,"w":210,"h":118,"fullH":118,"n":4},{"id":"LLB Logo_CUSTOMERS","cluster":"LLB Logo","x":2167,"y":1032,"w":210,"h":137,"fullH":137,"n":5},{"id":"LLB Logo_PRODUCT_STOCKS","cluster":"LLB Logo","x":2167,"y":1199,"w":210,"h":137,"fullH":137,"n":5}],"edges":[{"a":"USERS","b":"MODEL_HAS_ROLES","ac":"||","bc":"o{","l":"has roles (morph)"},{"a":"USERS","b":"MODEL_HAS_PERMISSIONS","ac":"||","bc":"o{","l":"direct permissions (morph)"},{"a":"USERS","b":"PERSONAL_ACCESS_TOKENS","ac":"||","bc":"o{","l":"tokens (morph)"},{"a":"USERS","b":"NOTIFICATIONS","ac":"||","bc":"o{","l":"receives (morph)"},{"a":"USERS","b":"ACTIVITY_LOGS","ac":"||","bc":"o{","l":"causes (morph)"},{"a":"CLIENTS","b":"PERSONAL_ACCESS_TOKENS","ac":"||","bc":"o{","l":"tokens (morph)"},{"a":"CLIENTS","b":"NOTIFICATIONS","ac":"||","bc":"o{","l":"receives (morph)"},{"a":"ROLES","b":"MODEL_HAS_ROLES","ac":"||","bc":"o{","l":"assigned to"},{"a":"ROLES","b":"ROLE_HAS_PERMISSIONS","ac":"||","bc":"o{","l":"grants"},{"a":"PERMISSIONS","b":"MODEL_HAS_PERMISSIONS","ac":"||","bc":"o{","l":"assigned to"},{"a":"PERMISSIONS","b":"ROLE_HAS_PERMISSIONS","ac":"||","bc":"o{","l":"granted via"},{"a":"USERS","b":"PASSWORD_RESET_TOKENS","ac":"||","bc":"o|","l":"reset (super-admin only)"},{"a":"CLIENTS","b":"CLIENT_PASSWORD_RESET_TOKENS","ac":"||","bc":"o|","l":"reset (own broker)"},{"a":"COMPANIES","b":"DEPARTMENTS","ac":"||","bc":"o{","l":"has"},{"a":"COMPANIES","b":"TEAMS","ac":"||","bc":"o{","l":"has"},{"a":"COMPANIES","b":"EMPLOYEES","ac":"||","bc":"o{","l":"employs"},{"a":"COMPANIES","b":"PROJECTS","ac":"||","bc":"o{","l":"owns"},{"a":"DEPARTMENTS","b":"TEAMS","ac":"||","bc":"o{","l":"has"},{"a":"DEPARTMENTS","b":"EMPLOYEES","ac":"||","bc":"o{","l":"has"},{"a":"DEPARTMENTS","b":"PROJECTS","ac":"||","bc":"o{","l":"scopes (from team)"},{"a":"DESIGNATIONS","b":"EMPLOYEES","ac":"|o","bc":"o{","l":"held by"},{"a":"USERS","b":"EMPLOYEES","ac":"||","bc":"o{","l":"employed as (1 per company)"},{"a":"TEAMS","b":"TEAM_MEMBERS","ac":"||","bc":"o{","l":"has"},{"a":"EMPLOYEES","b":"TEAM_MEMBERS","ac":"||","bc":"o{","l":"member of (leader or member)"},{"a":"CLIENTS","b":"PROJECTS","ac":"||","bc":"o{","l":"contracts"},{"a":"TEAMS","b":"PROJECTS","ac":"||","bc":"o{","l":"handles"},{"a":"EMPLOYEES","b":"PROJECTS","ac":"|o","bc":"o{","l":"assigned marketer"},{"a":"PROJECTS","b":"PROJECT_MILESTONES","ac":"||","bc":"o{","l":"split into monthly"},{"a":"PROJECTS","b":"SALES_REPORTS","ac":"||","bc":"o{","l":"weekly entry"},{"a":"PROJECTS","b":"PROJECT_SALES","ac":"||","bc":"o{","l":"has"},{"a":"PROJECTS","b":"PROJECT_ASSIGNMENTS","ac":"||","bc":"o{","l":"ownership history"},{"a":"PROJECTS","b":"PROJECT_NOTES","ac":"||","bc":"o{","l":"has"},{"a":"PROJECT_MILESTONES","b":"PROJECT_SALES","ac":"|o","bc":"o{","l":"attributes"},{"a":"TEAMS","b":"PROJECT_ASSIGNMENTS","ac":"||","bc":"o{","l":"has"},{"a":"EMPLOYEES","b":"PROJECT_ASSIGNMENTS","ac":"||","bc":"o{","l":"has"},{"a":"TEAMS","b":"PROJECT_SALES","ac":"|o","bc":"o{","l":"credited"},{"a":"EMPLOYEES","b":"PROJECT_SALES","ac":"|o","bc":"o{","l":"credited"},{"a":"USERS","b":"PROJECT_NOTES","ac":"|o","bc":"o{","l":"authors"},{"a":"COMPANIES","b":"PROJECT_MILESTONES","ac":"||","bc":"o{","l":"scopes"},{"a":"COMPANIES","b":"SALES_REPORTS","ac":"||","bc":"o{","l":"scopes"},{"a":"COMPANIES","b":"PROJECT_SALES","ac":"||","bc":"o{","l":"scopes"},{"a":"COMPANIES","b":"PROJECT_ASSIGNMENTS","ac":"||","bc":"o{","l":"scopes"},{"a":"COMPANIES","b":"PROJECT_NOTES","ac":"||","bc":"o{","l":"scopes"},{"a":"USERS","b":"CALL_CENTER_AGENTS","ac":"||","bc":"o|","l":"may be an agent"},{"a":"EMPLOYEES","b":"CALL_CENTER_AGENTS","ac":"||","bc":"o{","l":"payout identity"},{"a":"USERS","b":"CALL_CENTER_PICKS","ac":"||","bc":"o{","l":"picks"},{"a":"EMPLOYEES","b":"CALL_CENTER_PICKS","ac":"||","bc":"o{","l":"credited"},{"a":"CALL_CENTER_PICKS","b":"CALL_CENTER_ACTIVITIES","ac":"||","bc":"o{","l":"timeline of"},{"a":"USERS","b":"CALL_CENTER_ACTIVITIES","ac":"||","bc":"o{","l":"performs"},{"a":"CALL_CENTER_PICKS","b":"LLB Logo_ORDERS","ac":"}o","bc":"o|","l":"order_id (no FK)"},{"a":"CALL_CENTER_ACTIVITIES","b":"LLB Logo_ORDERS","ac":"}o","bc":"o|","l":"order_id (no FK)"},{"a":"LLB Logo_ORDERS","b":"LLB Logo_ORDER_ITEMS","ac":"||","bc":"o{","l":"contains"},{"a":"LLB Logo_ORDERS","b":"LLB Logo_ORDER_SHIPPING_ADDRESSES","ac":"||","bc":"o|","l":"ships to"},{"a":"LLB Logo_ORDERS","b":"LLB Logo_ORDER_LOGS","ac":"||","bc":"o{","l":"merchant timeline"},{"a":"LLB Logo_CUSTOMERS","b":"LLB Logo_ORDERS","ac":"||","bc":"o{","l":"places"},{"a":"LLB Logo_ORDER_ITEMS","b":"LLB Logo_PRODUCT_STOCKS","ac":"}o","bc":"o|","l":"moves stock"},{"a":"LLB Logo_ORDERS","b":"LLB Logo_ORDERS","ac":"||","bc":"o|","l":"dropshipping pair (parent_id)"}],"clusters":[{"id":"identity","title":"Identity & access","color":"#4f46e5","x":44,"y":160,"w":673,"h":1213},{"id":"org","title":"Organisation","color":"#0d9488","x":785,"y":160,"w":262,"h":1088},{"id":"projects","title":"Projects & performance","color":"#c2410c","x":1115,"y":160,"w":578,"h":1191},{"id":"callcenter","title":"Call center (CRM)","color":"#be123c","x":1761,"y":160,"w":312,"h":758},{"id":"LLB Logo","title":"LLB Logo inventory DB (external)","color":"#7c3aed","x":2141,"y":160,"w":330,"h":1202}]};
function packLayout(nodes, clusters) {
  const MAXH = 1180, GAPY = 30, GAPX = 46, CGAP = 120, TOP = 212
  let x = 70
  for (const c of clusters) {
    const list = nodes.filter(n => n.cluster === c.id && !n.hidden)
    if (!list.length) { c.x = x - 26; c.y = TOP - 52; c.w = 0; c.h = 0; continue }
    const cols = [[]]
    let h = 0
    for (const n of list) {
      if (h + n.h > MAXH && cols[cols.length - 1].length) { cols.push([]); h = 0 }
      cols[cols.length - 1].push(n)
      h += n.h + GAPY
    }
    let cx = x, tallest = 0
    for (const column of cols) {
      const w = Math.max.apply(null, column.map(n => n.w))
      let cy = TOP
      for (const n of column) { n.x = cx; n.y = cy; cy += n.h + GAPY }
      tallest = Math.max(tallest, cy - TOP - GAPY)
      cx += w + GAPX
    }
    c.x = x - 26
    c.y = TOP - 52
    c.w = cx - GAPX - x + 52
    c.h = tallest + 78
    x = cx - GAPX + CGAP
  }
}
function layoutEdges(nodes, edges) {
  const byId = {}
  for (const n of nodes) byId[n.id] = n
  const sides = {}
  const pick = []
  for (const e of edges) {
    const a = byId[e.a], b = byId[e.b]
    if (!a || !b) { pick.push(null); continue }
    if (a === b) { pick.push({ self: true, a: a, b: b }); continue }
    const acx = a.x + a.w / 2, acy = a.y + a.h / 2
    const bcx = b.x + b.w / 2, bcy = b.y + b.h / 2
    const dx = bcx - acx, dy = bcy - acy
    let sa, sb
    if (Math.abs(dx) * 1.15 >= Math.abs(dy)) {
      sa = dx >= 0 ? 'R' : 'L'; sb = dx >= 0 ? 'L' : 'R'
    } else {
      sa = dy >= 0 ? 'B' : 'T'; sb = dy >= 0 ? 'T' : 'B'
    }
    const ka = a.id + sa, kb = b.id + sb
    sides[ka] = (sides[ka] || 0) + 1
    sides[kb] = (sides[kb] || 0) + 1
    pick.push({ a: a, b: b, sa: sa, sb: sb, ia: sides[ka], ib: sides[kb], ka: ka, kb: kb })
  }
  const seen = {}
  const out = []
  for (let i = 0; i < pick.length; i++) {
    const p = pick[i]
    if (!p) { out.push(null); continue }
    if (p.self) {
      const n = p.a
      const x = n.x + n.w, y = n.y + n.h / 2
      out.push({
        d: 'M' + x + ' ' + (y - 14) + 'C' + (x + 90) + ' ' + (y - 60) + ' ' + (x + 90) + ' ' + (y + 60) + ' ' + x + ' ' + (y + 14),
        ax: x, ay: y - 14, adx: 1, ady: 0,
        bx: x, by: y + 14, bdx: 1, bdy: 0,
        mx: x + 66, my: y,
      })
      continue
    }
    const anchor = function (n, side, idx, total) {
      const f = total <= 1 ? 0.5 : (idx / (total + 1))
      if (side === 'L') return [n.x, n.y + n.h * clamp(f), -1, 0]
      if (side === 'R') return [n.x + n.w, n.y + n.h * clamp(f), 1, 0]
      if (side === 'T') return [n.x + n.w * clamp(f), n.y, 0, -1]
      return [n.x + n.w * clamp(f), n.y + n.h, 0, 1]
    }
    function clamp(f) { return Math.max(0.16, Math.min(0.84, f)) }
    seen[p.ka] = (seen[p.ka] || 0) + 1
    seen[p.kb] = (seen[p.kb] || 0) + 1
    const A = anchor(p.a, p.sa, seen[p.ka], sides[p.ka])
    const B = anchor(p.b, p.sb, seen[p.kb], sides[p.kb])
    const dist = Math.hypot(B[0] - A[0], B[1] - A[1])
    const k = Math.max(50, Math.min(190, dist * 0.42))
    const c1x = A[0] + A[2] * k, c1y = A[1] + A[3] * k
    const c2x = B[0] + B[2] * k, c2y = B[1] + B[3] * k
    out.push({
      d: 'M' + r(A[0]) + ' ' + r(A[1]) + 'C' + r(c1x) + ' ' + r(c1y) + ' ' + r(c2x) + ' ' + r(c2y) + ' ' + r(B[0]) + ' ' + r(B[1]),
      ax: A[0], ay: A[1], adx: A[2], ady: A[3],
      bx: B[0], by: B[1], bdx: B[2], bdy: B[3],
      mx: (A[0] + c1x + c2x + B[0]) / 4, my: (A[1] + c1y + c2y + B[1]) / 4,
    })
  }
  function r(v) { return Math.round(v * 10) / 10 }
  return out
}
function markerPath(card, atStart) {
  const chars = atStart ? card.split('') : card.split('').reverse()
  let d = 0
  const parts = []
  for (const ch of chars) {
    if (ch === '|') { parts.push({ t: 'bar', d: d + 5 }); d += 11 }
    else if (ch === 'o') { parts.push({ t: 'dot', d: d + 6 }); d += 13 }
    else { parts.push({ t: 'crow', d: d }); d += 15 }
  }
  return parts
}
var svg=document.getElementById('erd');
var vp=document.getElementById('viewport');
var nodeEls={},edgeEls=[],labelEls=[];
var nodes=M.nodes, edges=M.edges, clusters=M.clusters;
var byId={}; nodes.forEach(function(n,i){byId[n.id]=n; n.i=i;});
[].forEach.call(document.querySelectorAll('#nodes .node'),function(el){nodeEls[el.getAttribute('data-id')]=el;});
[].forEach.call(document.querySelectorAll('#edges .edge'),function(el,i){edgeEls[i]=el;});
[].forEach.call(document.querySelectorAll('#elabels .elabel'),function(el,i){labelEls[i]=el;});
var nb={}; nodes.forEach(function(n){nb[n.id]=[];});
edges.forEach(function(e,i){ if(nb[e.a])nb[e.a].push(i); if(nb[e.b]&&e.b!==e.a)nb[e.b].push(i); });

var view={k:1,x:0,y:0};
function applyView(){vp.setAttribute('transform','translate('+view.x+','+view.y+') scale('+view.k+')');}

function markerSvgAttrs(g,parts,x,y,dx,dy){
  var ang=Math.atan2(dy,dx)*180/Math.PI;
  g.setAttribute('transform','translate('+x+','+y+') rotate('+ang+')');
  var kids=g.childNodes,i=0;
  parts.forEach(function(p){
    var el=kids[i++]; if(!el)return;
    if(p.t==='bar') el.setAttribute('d','M'+p.d+' -6.5L'+p.d+' 6.5');
    else if(p.t==='dot'){ el.setAttribute('cx',p.d); }
    else el.setAttribute('d','M'+p.d+' -6.5L'+(p.d+14)+' 0L'+p.d+' 6.5M'+p.d+' 0L'+(p.d+14)+' 0');
  });
}
function redrawEdges(){
  var geo=layoutEdges(nodes,edges.map(function(e){return {a:e.a,b:e.b};}));
  geo.forEach(function(g,i){
    var el=edgeEls[i]; if(!el||!g)return;
    el.childNodes[0].setAttribute('d',g.d);
    el.childNodes[1].setAttribute('d',g.d);
    markerSvgAttrs(el.childNodes[2],markerPath(edges[i].ac,true),g.ax,g.ay,g.adx,g.ady);
    markerSvgAttrs(el.childNodes[3],markerPath(edges[i].bc,false),g.bx,g.by,g.bdx,g.bdy);
    var t=labelEls[i]&&labelEls[i].firstChild;
    if(t){ t.setAttribute('x',Math.round(g.mx)); t.setAttribute('y',Math.round(g.my)); }
  });
}
function placeNodes(){
  nodes.forEach(function(n){
    var el=nodeEls[n.id];
    el.setAttribute('transform','translate('+n.x+','+n.y+')');
    el.firstChild.setAttribute('height',n.h);
  });
}
function relayout(){ packLayout(nodes,clusters); placeNodes(); redrawClusters(); redrawEdges(); }
function redrawClusters(){
  clusters.forEach(function(c){
    var g=document.querySelector('.cluster[data-cluster="'+c.id+'"]');
    var r=g.firstChild, t=g.childNodes[1];
    r.setAttribute('x',c.x); r.setAttribute('y',c.y);
    r.setAttribute('width',c.w); r.setAttribute('height',c.h);
    t.setAttribute('x',c.x+22); t.setAttribute('y',c.y+32);
  });
}

/* ── focus / hover ─────────────────────────────────────────── */
var pinned=null;
function focus(id){
  if(!id){ svg.classList.remove('focusing');
    [].forEach.call(document.querySelectorAll('.on'),function(e){e.classList.remove('on');});
    return; }
  svg.classList.add('focusing');
  [].forEach.call(document.querySelectorAll('.on'),function(e){e.classList.remove('on');});
  nodeEls[id].classList.add('on');
  nb[id].forEach(function(i){
    edgeEls[i].classList.add('on');
    if(labelEls[i])labelEls[i].classList.add('on');
    var o=edges[i].a===id?edges[i].b:edges[i].a;
    if(nodeEls[o])nodeEls[o].classList.add('on');
  });
  var c=byId[id].cluster;
  var cl=document.querySelector('.cluster[data-cluster="'+c+'"]');
  if(cl)cl.classList.add('on');
}
nodes.forEach(function(n){
  var el=nodeEls[n.id];
  el.addEventListener('mouseenter',function(){ if(!pinned&&!dragging)focus(n.id); });
  el.addEventListener('mouseleave',function(){ if(!pinned&&!dragging)focus(null); });
  el.addEventListener('click',function(ev){
    ev.stopPropagation();
    if(moved)return;
    if(ev.shiftKey||ev.altKey){ toggleCollapse(n); return; }
    pinned = (pinned===n.id)?null:n.id;
    focus(pinned);
  });
  el.addEventListener('dblclick',function(ev){ ev.stopPropagation(); toggleCollapse(n); });
});
function toggleCollapse(n){
  n.collapsed=!n.collapsed;
  n.h = n.collapsed ? M.HEADER_H : n.fullH;
  nodeEls[n.id].classList.toggle('collapsed',n.collapsed);
  relayout();
}

/* ── pan / zoom / drag ─────────────────────────────────────── */
var dragging=null,moved=false,panning=null;
function ptr(ev){ var p=svg.createSVGPoint(); p.x=ev.clientX; p.y=ev.clientY;
  return p.matrixTransform(vp.getScreenCTM().inverse()); }
svg.addEventListener('mousedown',function(ev){
  var g=ev.target.closest?ev.target.closest('.node'):null;
  moved=false;
  if(g&&!ev.target.closest('#ui')){
    var n=byId[g.getAttribute('data-id')];
    var p=ptr(ev);
    dragging={n:n,ox:p.x-n.x,oy:p.y-n.y};
  } else if(!ev.target.closest('#ui')){
    panning={x:ev.clientX,y:ev.clientY,vx:view.x,vy:view.y};
  }
});
window.addEventListener('mousemove',function(ev){
  if(dragging){ var p=ptr(ev); dragging.n.x=p.x-dragging.ox; dragging.n.y=p.y-dragging.oy;
    moved=true; placeNodes(); redrawEdges(); }
  else if(panning){ var dx=ev.clientX-panning.x, dy=ev.clientY-panning.y;
    if(Math.abs(dx)+Math.abs(dy)>3)moved=true;
    view.x=panning.vx+dx; view.y=panning.vy+dy; applyView(); }
});
window.addEventListener('mouseup',function(){ dragging=null; panning=null; setTimeout(function(){moved=false;},0); });
svg.addEventListener('click',function(ev){ if(ev.target.closest('#ui'))return; if(moved)return; pinned=null; focus(null); });
svg.addEventListener('wheel',function(ev){
  ev.preventDefault();
  var f=ev.deltaY<0?1.12:1/1.12;
  var p=svg.createSVGPoint(); p.x=ev.clientX; p.y=ev.clientY;
  var m=p.matrixTransform(svg.getScreenCTM().inverse());
  view.x=m.x-(m.x-view.x)*f; view.y=m.y-(m.y-view.y)*f; view.k*=f;
  applyView();
},{passive:false});
function zoom(f){ var cx=M.W/2,cy=M.H/2;
  view.x=cx-(cx-view.x)*f; view.y=cy-(cy-view.y)*f; view.k*=f; applyView(); }
function fit(){
  view={k:1,x:0,y:0}; applyView();
  var b=vp.getBBox(), pad=60;
  if(!b.width||!b.height)return;
  var k=Math.min((M.W-pad*2)/b.width,(M.H-pad*2-140)/b.height);
  view.k=k;
  view.x=(M.W-b.width*k)/2-b.x*k;
  view.y=(M.H-140-b.height*k)/2-b.y*k+140;
  applyView();
}

/* ── search ────────────────────────────────────────────────── */
var q='',sBox=document.getElementById('search'),sTxt=document.getElementById('searchtext');
function runSearch(){
  sBox.classList.toggle('idle',q==='');
  sTxt.textContent = q ? 'search: '+q : '';
  var hits=0;
  nodes.forEach(function(n){
    var m = q!=='' && n.id.toLowerCase().indexOf(q.toLowerCase())>=0;
    nodeEls[n.id].classList.toggle('match',m);
    if(m)hits++;
  });
  if(q)sTxt.textContent='search: '+q+'   ('+hits+')';
}
window.addEventListener('keydown',function(ev){
  if(ev.key==='Escape'){ q=''; runSearch(); pinned=null; focus(null); return; }
  if(ev.key==='Backspace'){ q=q.slice(0,-1); runSearch(); ev.preventDefault(); return; }
  if(ev.key==='+'||ev.key==='='){ zoom(1.15); return; }
  if(ev.key==='-'){ zoom(1/1.15); return; }
  if(ev.key==='0'){ fit(); return; }
  if(ev.key.length===1&&/[a-zA-Z0-9_]/.test(ev.key)){ q+=ev.key; runSearch(); }
});

/* ── ui buttons ────────────────────────────────────────────── */
function on(id,fn){ var el=document.getElementById(id); if(el)el.addEventListener('click',function(ev){ev.stopPropagation();fn(el);}); }
on('b-in',function(){zoom(1.15);});
on('b-out',function(){zoom(1/1.15);});
on('b-fit',fit);
on('b-collapse',function(el){
  var anyOpen=nodes.some(function(n){return !n.collapsed;});
  nodes.forEach(function(n){ n.collapsed=anyOpen; n.h=anyOpen?M.HEADER_H:n.fullH;
    nodeEls[n.id].classList.toggle('collapsed',anyOpen); });
  el.classList.toggle('active',anyOpen);
  el.querySelector('text').textContent = anyOpen?'Expand all':'Collapse all';
  relayout();
});
on('b-reset',function(){ nodes.forEach(function(n){n.collapsed=false;n.h=n.fullH;
  nodeEls[n.id].classList.remove('collapsed');});
  var b=document.getElementById('b-collapse');
  b.classList.remove('active'); b.querySelector('text').textContent='Collapse all';
  q=''; runSearch(); pinned=null; focus(null); relayout(); fit(); });

clusters.forEach(function(c){
  var lg=document.querySelector('.legend[data-cluster="'+c.id+'"]');
  if(!lg)return;
  lg.addEventListener('click',function(ev){
    ev.stopPropagation();
    var off=!lg.classList.contains('off');
    lg.classList.toggle('off',off);
    document.querySelector('.cluster[data-cluster="'+c.id+'"]').classList.toggle('off',off);
    nodes.forEach(function(n){ if(n.cluster===c.id){ n.hidden=off; nodeEls[n.id].classList.toggle('hidden',off); } });
    edges.forEach(function(e,i){
      var hide=(byId[e.a]&&byId[e.a].cluster===c.id&&off)||(byId[e.b]&&byId[e.b].cluster===c.id&&off);
      var h2=hide;
      if(!off){
        h2=[byId[e.a],byId[e.b]].some(function(n){
          return n&&document.querySelector('.legend[data-cluster="'+n.cluster+'"]').classList.contains('off');});
      }
      edgeEls[i].classList.toggle('hidden',h2);
      if(labelEls[i])labelEls[i].classList.toggle('hidden',h2);
    });
    relayout();
  });
});
edgeEls.forEach(function(el,i){
  el.addEventListener('click',function(ev){ ev.stopPropagation(); });
  el.addEventListener('mouseenter',function(){ if(labelEls[i])labelEls[i].classList.add('hovered'); });
  el.addEventListener('mouseleave',function(){ if(labelEls[i])labelEls[i].classList.remove('hovered'); });
});
applyView();
})();
